# Generated by build.py from recipe.yml for recipe pop3-move-a-mail-client-to-imap. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--mail-domain', 'example.com', '--mailbox', 'ann@example.com:s3cret', '-v', '--log-file', 'surl.log', 'smtp://127.0.0.1:8080/', 'pop3://127.0.0.1:8081/', 'imap://127.0.0.1:8082/' -PassThru -NoNewWindow
Start-Sleep 1
curl.exe -sS --crlf -u ann@example.com:s3cret --mail-from shop@example.com --mail-rcpt ann@example.com -T "order[1-2].eml" smtp://127.0.0.1:8080/example.com
curl.exe -sS -o NUL --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:s3cret -X "FETCH 2 FLAGS" imap://127.0.0.1:8082/INBOX
curl.exe -sS --crlf -u ann@example.com:s3cret --mail-from shop@example.com --mail-rcpt ann@example.com -T "order[1-2].eml" smtp://127.0.0.1:8083/example.com
curl.exe -sS -o NUL --retry 10 --retry-all-errors --retry-delay 1 -u ann@example.com:s3cret -X "FETCH 2 FLAGS" imap://127.0.0.1:8085/INBOX
try { curl.exe -sS -u ann@example.com:s3cret -o over-pop3.eml pop3://127.0.0.1:8081/1 --next -sS -u ann@example.com:s3cret -o over-imap.eml "imap://127.0.0.1:8082/INBOX;UID=1" && cmp over-pop3.eml over-imap.eml && echo identical } finally { Stop-Process $server0 }
